/// Lesson sections for the info page — never shown on the practice screen.
const List<TechniqueSection> setFillSixGroupsLesson = [
  TechniqueSection(
    title: "Why it matters",
    body:
        "Groups of six over four beats put the accents on 1, the \"and\" of 2 and 4, while the drums in this sheet change on the beats. Accent and drum run against each other, and that friction is what makes the fill sound modern. It is the pad sheet \"Six-Note Groups Fill\" on the kit.",
  ),
  TechniqueSection(
    title: "How to play it",
    body:
        "Three bars of funk sixteenths, crash on the one of bar 1; in the fill bar the kick keeps 1 and 3. Line 1: beats 1 and 2 on the snare with accents on 1 and on the \"and\" of 2, beat 3 on the high tom, beat 4 on the floor tom with the accent on 4. Accented notes full height, the rest low and even.",
  ),
  TechniqueSection(
    title: "Practice tips",
    body:
        "Line 2 is the paradiddle-diddle over snare, high tom, mid tom and floor tom. Line 4 plays the double paradiddle on high tom and floor tom, the left-hand accent on the \"and\" of 2. Line 5 is R L L in threes on the snare, accents on 1, the \"a\" of 1, the \"and\" of 2 and the \"e\" of 3, and a group of four on the floor tom. Clap the accents first, then play them on the drums. Toms accept any tom and the crash any crash, so a kit with fewer drums plays the sheet too: the mid tom and the second floor tom go to the nearest tom you have.",
  ),
  TechniqueSection(
    title: "Where you hear it",
    body:
        "Funk, fusion and gospel drumming, the over-the-bar phrases of Dave Weckl and Jojo Mayer.",
  ),
];
